(function () {
  var tabs = ['kasko', 'osago'];
  function show(tab, link) {
    if (tabs.indexOf(tab) < 0) tab = 'kasko';
    tabs.forEach(function (t) { document.getElementById(t).hidden = t !== tab; });
    document.querySelectorAll('.fx-tab').forEach(function (b) { b.setAttribute('aria-selected', String(b.dataset.tab === tab)); });
    if (link) dash.setLink(tab);
  }
  document.querySelectorAll('.fx-tab').forEach(function (b) { b.addEventListener('click', function () { show(b.dataset.tab, true); }); });
  show(location.hash.slice(1), false);
  var metric = document.getElementById('metric');
  metric.addEventListener('change', function () { dash.setParams({ metric: metric.value }); });
  function draw() {
    var p = Object.assign({ metric: 'cnt' }, dash.params());
    metric.value = p.metric;
    var t = dash.data('k_total');
    document.getElementById('k-total').textContent = t.status === 'ok' ? String(t.data[0][p.metric]) : t.status;
    var o = dash.data('o_count');
    document.getElementById('o-count').textContent = o.status === 'ok' ? String(o.data[0].n) : o.status;
    document.getElementById('k-status').textContent = 'Расчёт с ошибкой: ' + dash.data('broken').status + ', d3: ' + (window.d3 && window.d3.stub ? 'заглушка' : 'нет');
  }
  dash.onData(draw);
})();
